    stops = []
    for i, row in enumerate(reader):
        if i == 0:
            continue
        stop_id = int(row[0])
        stop_name = row[1]
        stop_lat = float(row[2])
        stop_lon = float(row[3])
        stops.append((stop_id, stop_name, stop_lat, stop_lon))

# Count duplicates
stop_counts = {}
for stop_id, stop_name, stop_lat, stop_lon in stops:
    stop_counts[stop_id] = stop_counts.get(stop_id, 0) + 1

print("Stop counts:")
for sid, count in sorted(stop_counts.items()):
    if count > 1:
        print(f"  {sid}: {count} duplicates")
    elif count == 1:
